const formatarMoeda = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(Number(v || 0));
const formatarNumeroBR = (v, casas = 0) => Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas });
const formatarDataHoraBR = (valor) => {
  if (!valor) return '-';
  const data = new Date(valor);
  if (Number.isNaN(data.getTime())) return String(valor);
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'America/Fortaleza',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(data);
};
const calcularUpa = (totalItens, atividadeRealizada) => {
  const itens = Number(totalItens || 0);
  const atividade = Number(atividadeRealizada || 0);
  return atividade > 0 ? itens / atividade : 0;
};
const formatarAbrev = (v) => {
  const a = Math.abs(Number(v || 0)); const s = Number(v || 0) < 0 ? '-' : '';
  if (a >= 1000000) return `${s}R$${(a / 1000000).toLocaleString('pt-BR', { maximumFractionDigits: 2 })} Mi`;
  if (a >= 1000) return `${s}R$${(a / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 2 })} Mil`;
  return `${s}R$${a.toLocaleString('pt-BR')}`;
};


const formatarMoedaRotuloGrafico = (valor) => {
  const numero = Number(valor || 0);
  const absoluto = Math.abs(numero);
  const sinal = numero < 0 ? '-' : '';

  if (absoluto >= 1000000) {
    return `${sinal}R$ ${(absoluto / 1000000).toLocaleString('pt-BR', {
      minimumFractionDigits: 1,
      maximumFractionDigits: 2,
    })} Mi`;
  }

  if (absoluto >= 1000) {
    return `${sinal}R$ ${(absoluto / 1000).toLocaleString('pt-BR', {
      minimumFractionDigits: 1,
      maximumFractionDigits: 2,
    })} Mil`;
  }

  return `${sinal}${formatarMoeda(absoluto)}`;
};

const renderizarRotuloModeloVenda = ({
  cx,
  cy,
  midAngle,
  outerRadius,
  name,
  value,
  percent,
}) => {
  const radianos = Math.PI / 180;
  const angulo = -Number(midAngle || 0) * radianos;
  const raioBase = Number(outerRadius || 0);
  const raioInicio = raioBase + 2;
  const raioCotovelo = raioBase + 16;
  const cos = Math.cos(angulo);
  const sen = Math.sin(angulo);

  const xInicio = Number(cx || 0) + raioInicio * cos;
  const yInicio = Number(cy || 0) + raioInicio * sen;
  const xCotovelo = Number(cx || 0) + raioCotovelo * cos;
  const yCotovelo = Number(cy || 0) + raioCotovelo * sen;
  const ladoDireito = cos >= 0;
  const xFim = xCotovelo + (ladoDireito ? 10 : -10);
  const xTexto = xFim + (ladoDireito ? 4 : -4);
  const ancora = ladoDireito ? 'start' : 'end';
  const percentual = Number(percent || 0) * 100;

  return (
    <g pointerEvents="none">
      <path
        d={`M${xInicio},${yInicio}L${xCotovelo},${yCotovelo}L${xFim},${yCotovelo}`}
        fill="none"
        stroke="#94a3b8"
        strokeWidth={1}
      />
      <circle cx={xInicio} cy={yInicio} r={2} fill="#64748b" />
      <text
        x={xTexto}
        y={yCotovelo - 3}
        textAnchor={ancora}
        fill="#334155"
        fontSize={10}
        fontWeight={900}
      >
        {formatarMoedaRotuloGrafico(value)}
      </text>
      <text
        x={xTexto}
        y={yCotovelo + 10}
        textAnchor={ancora}
        fill="#64748b"
        fontSize={8.5}
        fontWeight={700}
      >
        {`${String(name || 'Modelo')} • ${percentual.toLocaleString('pt-BR', {
          minimumFractionDigits: 1,
          maximumFractionDigits: 1,
        })}%`}
      </text>
    </g>
  );
};
const formatarMoedaCompactaCard = (v) => {
  const n = Number(v || 0);
  const a = Math.abs(n);
  const s = n < 0 ? '-' : '';
  if (a >= 1000000) return `${s}R$${(a / 1000000).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} Mi`;
  if (a >= 1000) return `${s}R$${(a / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} Mil`;
  return `${s}${formatarMoeda(a)}`;
};
const formatarTickMoeda = (v) => {
  const n = Number(v || 0);
  if (n >= 1000000) return `R$${(n / 1000000).toLocaleString('pt-BR', { maximumFractionDigits: 1 })} Mi`;
  if (n >= 1000) return `R$${(n / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 0 })}k`;
  return `R$${n.toLocaleString('pt-BR')}`;
};
const formatarDataBR = (d) => { if (!d) return '-'; const p = String(d).split('-'); return p.length === 3 ? `${p[2]}/${p[1]}/${p[0]}` : d; };


